SELECT s.id, s.symbol, s.interval_code, s.candle_open_time, s.generated_at, s.created_at, s.signal_mode, s.decision, s.original_decision, s.selected_strategy, s.market_regime, s.confirmed_regime, s.total_score, s.confidence_score, s.effective_confidence_score, s.final_entry_allowed, s.primary_blocking_stage, s.data_quality_valid, s.confluence_status, s.confluence_higher_decision, s.btc_context_status, s.btc_context_entry_allowed, s.btc_correlation, s.liquidity_status, s.derivatives_status, s.latest_price, s.stop_loss, s.take_profit, s.risk_reward_ratio, s.atr_percent, s.atr_entry_type, s.atr_recommended_position_percent, s.atr_overextended, s.entry_authority, LEFT(s.decision_path, 1500) AS decision_path FROM crypto_ai.trade_signal s WHERE s.id IN (SELECT signal_id FROM crypto_ai.paper_position WHERE id IN (182,172,162,158,143,137) UNION SELECT exit_signal_id FROM crypto_ai.paper_position WHERE id IN (182,172,162,158,143,137) AND exit_signal_id IS NOT NULL) ORDER BY s.symbol, s.generated_at;